```ts
// authority:cross-graph-index — guarantees the materialized cross-graph
// reverse-index is present and schema-valid. Staleness detection is out
// of scope for this audit (too slow for CI); a scheduled health:snapshot
// task handles fresh rebuilds.

import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';

import { CrossGraphIndexSchema } from '../../../../src/natural/schema/crossGraphIndex';

import { type Audit, type AuditResult, type AuditViolation, makeFailed } from './types';

const AUDIT = { name: 'authority:cross-graph-index', severity: 'error' } as const;
const INDEX_PATH = resolve(process.cwd(), 'knowledge/indexes/cross-graph.json');

export const crossGraphIndexAudit: Audit = {
  ...AUDIT,
  description:
    'knowledge/indexes/cross-graph.json exists, schema-validates against CrossGraphIndexSchema, and carries a non-empty sourceRevision + valid builtAt timestamp.',
  async check(): Promise<AuditResult> {
    const violations: AuditViolation[] = [];

    let raw: string;
    try {
      raw = await readFile(INDEX_PATH, 'utf-8');
    } catch (err) {
      violations.push({
        message: `Cross-graph index not found at ${INDEX_PATH}: ${err instanceof Error ? err.message : String(err)}`,
        path: INDEX_PATH,
      });
      return makeFailed(AUDIT, violations, `Cross-graph index missing.`);
    }

    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch (err) {
      violations.push({
        message: `Cross-graph index is not valid JSON: ${err instanceof Error ? err.message : String(err)}`,
        path: INDEX_PATH,
      });
      return makeFailed(AUDIT, violations, `Cross-graph index unparseable.`);
    }

    const result = CrossGraphIndexSchema.safeParse(parsed);
    if (!result.success) {
      for (const issue of result.error.issues) {
        violations.push({
          message: `Schema violation at ${issue.path.join('.')}: ${issue.message}`,
          path: INDEX_PATH,
        });
      }
      return makeFailed(AUDIT, violations, `Cross-graph index fails schema validation.`);
    }

    if (!result.data.sourceRevision || result.data.sourceRevision.length === 0) {
      violations.push({ message: 'sourceRevision is empty', path: INDEX_PATH });
    }

    const builtAt = Date.parse(result.data.builtAt);
    if (Number.isNaN(builtAt)) {
      violations.push({ message: `builtAt is not a valid ISO-8601 timestamp: ${result.data.builtAt}`, path: INDEX_PATH });
    }

    const summary = violations.length === 0
      ? `Cross-graph index present and schema-valid (sourceRevision=${result.data.sourceRevision.slice(0, 8)}).`
      : `Cross-graph index failed ${violations.length} check(s).`;
    return makeFailed(AUDIT, violations, summary);
  },
};
```

**If `CrossGraphIndexSchema` isn't exported from `src/natural/schema/crossGraphIndex.ts`**, derive a minimal inline Zod schema covering the fields the audit actually checks (`schemaVersion`, `builtAt`, `sourceRevision`, `entries`). Prefer reuse when available.

