```ts
// authority:formula-records — formula registry internal consistency.
// Every Formula.skeletonRef / Interpretation.skeletonRef resolves to a
// registered FormulaSkeleton. See vision authority matrix.

import { type Audit, type AuditResult, type AuditViolation, makeFailed } from './types';

const AUDIT = { name: 'authority:formula-records', severity: 'warn' } as const;

async function loadRegistries(): Promise<{
  formulas: ReadonlyArray<{ id: string; skeletonRef?: string }>;
  skeletons: ReadonlyArray<{ id: string }>;
  interpretations: ReadonlyArray<{ id: string; skeletonRef?: string }>;
}> {
  // Registries are loaded lazily so the audit can inspect them as data,
  // not as compile-time-reachable imports. Adjust import paths per the
  // actual export names discovered in Task 2 Step 1.
  const [
    { FORMULAS },
    { FORMULA_SKELETONS },
    { INTERPRETATIONS },
  ] = await Promise.all([
    // REPLACE these three paths with the actual export names + paths
    // identified in Step 1. If a registry doesn't exist yet, return [].
    import('../../../../src/natural/registry/formulas'),
    import('../../../../src/natural/registry/formulaSkeletons'),
    import('../../../../src/natural/registry/interpretations'),
  ]);

  return {
    formulas: FORMULAS ?? [],
    skeletons: FORMULA_SKELETONS ?? [],
    interpretations: INTERPRETATIONS ?? [],
  };
}

export const formulaRecordsAudit: Audit = {
  ...AUDIT,
  description:
    'Every Formula.skeletonRef and Interpretation.skeletonRef resolves to a registered FormulaSkeleton id.',
  async check(): Promise<AuditResult> {
    const violations: AuditViolation[] = [];

    let registries;
    try {
      registries = await loadRegistries();
    } catch (err) {
      // Registries may not exist yet; audit passes trivially. Record a
      // one-line summary naming the absent registry so health output
      // shows honest state.
      return makeFailed(AUDIT, [], `Formula registries not yet present (${err instanceof Error ? err.message : String(err)}) — audit vacuous.`);
    }

    const skeletonIds = new Set(registries.skeletons.map((s) => s.id));

    for (const f of registries.formulas) {
      if (f.skeletonRef !== undefined && !skeletonIds.has(f.skeletonRef)) {
        violations.push({
          message: `Formula '${f.id}' references unknown skeleton '${f.skeletonRef}'.`,
          details: { formulaId: f.id, skeletonRef: f.skeletonRef },
        });
      }
    }

    for (const i of registries.interpretations) {
      if (i.skeletonRef !== undefined && !skeletonIds.has(i.skeletonRef)) {
        violations.push({
          message: `Interpretation '${i.id}' references unknown skeleton '${i.skeletonRef}'.`,
          details: { interpretationId: i.id, skeletonRef: i.skeletonRef },
        });
      }
    }

    const summary = violations.length === 0
      ? `All formula/interpretation records reference valid skeletons (${registries.formulas.length} formulas, ${registries.interpretations.length} interpretations, ${registries.skeletons.length} skeletons).`
      : `${violations.length} formula/interpretation record(s) reference unknown skeletons.`;
    return makeFailed(AUDIT, violations, summary);
  },
};
```

**If the registry imports don't resolve** (file not found), the `catch` block returns a vacuous pass with an honest summary. That's the correct behavior — the audit is future-proofed for when the registries land without currently failing.

