- [ ] **Step 4: Implement the audit**

Create `scripts/health/checkers/authority/visual-registry.ts`:

```ts
// authority:visual-registry — the VisualRepresentation registry is the
// sole visual-artifact authority. No GuideEntity.demos[] usage remains;
// entityDemoRegistry is absent or empty; every visual record references
// a registered entity. See vision authority matrix row "Visual
// representations".

import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';

import { loadCanonicalVisual, DEFAULT_VISUAL_ROOT } from '../../../../src/visual/loaders/loadCanonicalVisual';
import { entityExists } from '../../../../src/entities/entityRegistry';

import { type Audit, type AuditResult, type AuditViolation, makeFailed } from './types';

const AUDIT = { name: 'authority:visual-registry', severity: 'error' } as const;
const DEMO_REGISTRY_PATH = resolve(process.cwd(), 'src/entities/entityDemoRegistry.ts');

function findDemosUsage(): AuditViolation[] {
  // Grep-style scan for `demos:` in src/entities/. Cheap enough at CI time.
  const violations: AuditViolation[] = [];
  const entitiesDir = resolve(process.cwd(), 'src/entities');
  if (!existsSync(entitiesDir)) return violations;

  const { readdirSync, statSync } = require('node:fs') as typeof import('node:fs');
  function walk(dir: string): void {
    for (const name of readdirSync(dir)) {
      const full = resolve(dir, name);
      const stat = statSync(full);
      if (stat.isDirectory()) {
        if (name === '__tests__') continue;
        walk(full);
        continue;
      }
      if (!name.endsWith('.ts') && !name.endsWith('.tsx')) continue;
      const src = readFileSync(full, 'utf-8');
      // Match property assignment `demos:` (not TypeScript `import {demos}`).
      const re = /^\s*demos:\s*\[/m;
      if (re.test(src)) {
        violations.push({
          message: `File ${full} still declares a 'demos:' property. Retired in favour of VisualRepresentation.`,
          path: full,
        });
      }
    }
  }
  walk(entitiesDir);
  return violations;
}

export const visualRegistryAudit: Audit = {
  ...AUDIT,
  description:
    'VisualRepresentation registry is the sole visual-artifact authority. No GuideEntity.demos[] remains; entityDemoRegistry is absent or empty; every visual record resolves to a registered entity.',
  async check(): Promise<AuditResult> {
    const violations: AuditViolation[] = [];

    // (1) No demos: usage in src/entities/
    violations.push(...findDemosUsage());

    // (2) entityDemoRegistry.ts is absent or empty
    if (existsSync(DEMO_REGISTRY_PATH)) {
      const contents = readFileSync(DEMO_REGISTRY_PATH, 'utf-8');
      // Accept the file only if it's a stub that exports nothing meaningful.
      if (/export\s+(const|function|default)\s+\w/.test(contents)) {
        violations.push({
          message: `entityDemoRegistry.ts still exports bindings. It must be fully retired — delete the file or reduce to a typing-only stub.`,
          path: DEMO_REGISTRY_PATH,
        });
      }
    }

    // (3) Every visual record's primary entity + additional entities resolve
    const records = await loadCanonicalVisual(DEFAULT_VISUAL_ROOT);
    for (const rec of records.values()) {
      const primaryId = rec.entity.primary;
      if (!entityExists(primaryId)) {
        violations.push({
          message: `Visual '${rec.id}' primary entity '${primaryId}' is not registered in ENTITY_INDEX.`,
          details: { visualId: rec.id, missingEntityId: primaryId },
        });
      }
      for (const additionalId of rec.entity.additional ?? []) {
        if (!entityExists(additionalId)) {
          violations.push({
            message: `Visual '${rec.id}' additional entity '${additionalId}' is not registered in ENTITY_INDEX.`,
            details: { visualId: rec.id, missingEntityId: additionalId },
          });
        }
      }
    }

    const summary = violations.length === 0
      ? `Visual registry is sole authority (${records.size} records, 0 parallel systems).`
      : `${violations.length} visual-registry violation(s).`;
    return makeFailed(AUDIT, violations, summary);
  },
};
```

**If `loadCanonicalVisual` or `DEFAULT_VISUAL_ROOT` isn't exported with those exact names**, inspect `src/visual/loaders/` to find the actual export and adjust. The `visualRepresentation.ts` schema import list (captured earlier) confirmed the loader path is correct.

