- [ ] **Step 3: Implement the classifier and migration runner**

Create `scripts/migrate/classify-prose-stability.ts`:

```ts
#!/usr/bin/env tsx
/**
 * One-shot migration: classify every prose YAML with a stability field.
 *
 *   stub     — any required section ≤ 50 chars trimmed, or any section
 *              contains a placeholder marker (case-insensitive):
 *              TODO, TBD, FIXME, placeholder, lorem ipsum.
 *   draft    — all required sections > 50 chars, no placeholder markers.
 *   canonical — NEVER assigned by the classifier. Earned manually.
 *
 * Retired after a single successful run (see Task 8 of the foundation-
 * hygiene plan).
 */

import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { glob } from 'node:fs/promises';

import yaml from 'js-yaml';

import { PROSE_TEMPLATES } from '../../src/natural/spec/prose';
import type { ProseEntityType, ProseStability } from '../../src/natural/schema/prose';

const PLACEHOLDER_MARKERS = [/\bTODO\b/i, /\bTBD\b/i, /\bFIXME\b/i, /\bplaceholder\b/i, /\blorem ipsum\b/i];
const MIN_SECTION_CHARS = 50;

interface InputRecord {
  entityType: ProseEntityType;
  canonical: { sections: Array<{ id: string; markdown: string }> };
  // Any other fields are passed through; the classifier is read-only.
}

export function classifyProseStability(record: InputRecord): ProseStability {
  const template = PROSE_TEMPLATES[record.entityType];
  const required = new Set<string>(template.required);

  const sectionById = new Map<string, string>();
  for (const s of record.canonical.sections) sectionById.set(s.id, s.markdown);

  for (const reqId of required) {
    const body = (sectionById.get(reqId) ?? '').trim();
    if (body.length <= MIN_SECTION_CHARS) return 'stub';
  }

  for (const s of record.canonical.sections) {
    for (const re of PLACEHOLDER_MARKERS) {
      if (re.test(s.markdown)) return 'stub';
    }
  }

  return 'draft';
}

interface MigrationSummary {
  total: number;
  byStability: Record<ProseStability, number>;
  byEntityType: Record<string, Record<ProseStability, number>>;
}

async function run(): Promise<MigrationSummary> {
  const files: string[] = [];
  for await (const f of glob('content/prose/**/*.yml', { cwd: process.cwd() })) {
    files.push(resolve(process.cwd(), f));
  }
  files.sort();

  const summary: MigrationSummary = {
    total: 0,
    byStability: { stub: 0, draft: 0, canonical: 0 },
    byEntityType: {},
  };

  for (const path of files) {
    const raw = await readFile(path, 'utf-8');
    const parsed = yaml.load(raw) as InputRecord & { stability?: ProseStability };
    if (parsed.stability !== undefined) {
      summary.total += 1;
      summary.byStability[parsed.stability] += 1;
      summary.byEntityType[parsed.entityType] ??= { stub: 0, draft: 0, canonical: 0 };
      summary.byEntityType[parsed.entityType][parsed.stability] += 1;
      continue; // already classified — idempotent
    }

    const stability = classifyProseStability(parsed);

    // Write the field as the FIRST key after entityType to keep the file
    // readable. Use a minimal string-splice approach so we don't reflow
    // the entire YAML (that destroys comments, ordering, formatting).
    const inserted = insertStabilityAfter(raw, stability, 'entityType');
    await writeFile(path, inserted, 'utf-8');

    summary.total += 1;
    summary.byStability[stability] += 1;
    summary.byEntityType[parsed.entityType] ??= { stub: 0, draft: 0, canonical: 0 };
    summary.byEntityType[parsed.entityType][stability] += 1;
  }

  return summary;
}

export function insertStabilityAfter(raw: string, stability: ProseStability, afterKey: string): string {
  // Find the first line starting with `<afterKey>:` and insert the new
  // stability line after it. Preserves the rest of the file verbatim.
  const lines = raw.split('\n');
  const idx = lines.findIndex((l) => l.startsWith(`${afterKey}:`));
  if (idx === -1) {
    throw new Error(`Cannot find '${afterKey}:' in YAML — refusing to modify unfamiliar layout.`);
  }
  lines.splice(idx + 1, 0, `stability: ${stability}`);
  return lines.join('\n');
}

async function main(): Promise<void> {
  const summary = await run();
  process.stdout.write(JSON.stringify(summary, null, 2) + '\n');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  await main();
}
```

**Note:** `node:fs/promises` `glob` is Node 22+. If the project's Node version is older, swap for a small glob shim using `readdir`/`readdirSync` with recursion. Check via `node --version` before committing.

