```ts
#!/usr/bin/env tsx
/**
 * Prose coverage report — three-tier + degree-weighted, mirroring
 * coverage-visual-artifacts.ts.
 *
 * Tiers:
 *   any              — entity has at least one ProseRecord.
 *   draftOrCanonical — entity has a record with stability ∈ {draft, canonical}.
 *   canonical        — entity has a record with stability = canonical.
 *
 * Weighting: per-entity {id, weight} accepted via `entityUniverse`. If
 * omitted (or string-array universe passed), all entities carry weight 1
 * and weighted coverage equals raw coverage.
 *
 * Usage:
 *   tsx scripts/audit/coverage-prose.ts
 *   tsx scripts/audit/coverage-prose.ts --format json
 *   tsx scripts/audit/coverage-prose.ts --strict
 */

import { loadCanonicalProse } from '../../src/prose/loaders/loadCanonicalProse';
import type { ProseEntityType, ProseStability } from '../../src/natural/schema/prose';
import { PROSE_ENTITY_TYPES } from '../../src/natural/spec/prose';

export type StabilityBreakdown = Record<ProseStability, number>;
export type CoverageTier = 'any' | 'draftOrCanonical' | 'canonical';

export interface EntityUniverseEntry {
  id: string;
  weight?: number;
}

export type EntityUniverseInput = readonly string[] | readonly EntityUniverseEntry[];

export interface TierCoverage {
  covered: number;
  rawCoverage: number;
  weightedCoverage: number;
}

export interface ProseKindCoverage {
  total: number;
  totalWeight: number;
  tiers: Record<CoverageTier, TierCoverage>;
  // Legacy flat fields kept in sync with tiers.any.
  covered: number;
  percent: number;
}

export interface ProseCoverageReport {
  totalRecords: number;
  byStability: StabilityBreakdown;
  coverageByEntityType: Record<ProseEntityType, ProseKindCoverage>;
  untrackedKinds: Record<string, number>;
  weighting: { formula: string; notes?: string };
}

export interface ComputeProseCoverageArgs {
  proseRoot?: string;
  entityUniverse?: Partial<Record<ProseEntityType, EntityUniverseInput>>;
  weightingNotes?: string;
}

const STABILITY_RANK: Record<ProseStability, number> = { stub: 1, draft: 2, canonical: 3 };

function normalize(slug: string): string {
  // Registry parameter IDs use legacy underscores (e.g. dynamic_viscosity);
  // prose entityRefs use canonical hyphens. Normalize both sides.
  return slug.replace(/_/g, '-');
}

function toUniverseEntries(u: EntityUniverseInput | undefined): EntityUniverseEntry[] {
  if (u === undefined) return [];
  if (u.length === 0) return [];
  if (typeof (u as readonly string[])[0] === 'string') {
    return (u as readonly string[]).map((id) => ({ id, weight: 1 }));
  }
  return (u as readonly EntityUniverseEntry[]).map((e) => ({ id: e.id, weight: e.weight ?? 1 }));
}

function emptyKindCoverage(): ProseKindCoverage {
  return {
    total: 0,
    totalWeight: 0,
    tiers: {
      any: { covered: 0, rawCoverage: 0, weightedCoverage: 0 },
      draftOrCanonical: { covered: 0, rawCoverage: 0, weightedCoverage: 0 },
      canonical: { covered: 0, rawCoverage: 0, weightedCoverage: 0 },
    },
    covered: 0,
    percent: 0,
  };
}

export async function computeProseCoverage(
  args: ComputeProseCoverageArgs = {},
): Promise<ProseCoverageReport> {
  const records = await loadCanonicalProse(args.proseRoot);

  // Index records by (entityType, normalized-slug) → highest stability.
  const maxStabilityByKey = new Map<string, ProseStability>();
  const byStability: StabilityBreakdown = { stub: 0, draft: 0, canonical: 0 };

  for (const rec of records.values()) {
    const stability = rec.stability;
    byStability[stability] += 1;
    const slug = normalize(rec.entityRef.slice(rec.entityRef.indexOf(':') + 1));
    const key = `${rec.entityType}\u0000${slug}`;
    const existing = maxStabilityByKey.get(key);
    if (existing === undefined || STABILITY_RANK[stability] > STABILITY_RANK[existing]) {
      maxStabilityByKey.set(key, stability);
    }
  }

  // Build coverage per entity type.
  const universe = args.entityUniverse ?? {};
  const coverageByEntityType = Object.fromEntries(
    PROSE_ENTITY_TYPES.map((t) => [t, emptyKindCoverage()]),
  ) as Record<ProseEntityType, ProseKindCoverage>;

  const untrackedKinds: Record<string, number> = {};

  for (const kind of PROSE_ENTITY_TYPES) {
    const entries = toUniverseEntries(universe[kind]);
    if (entries.length === 0) {
      // Count records for this kind so the report shows the gap.
      let count = 0;
      for (const key of maxStabilityByKey.keys()) {
        if (key.startsWith(`${kind}\u0000`)) count += 1;
      }
      if (count > 0) untrackedKinds[kind] = count;
      continue;
    }

    const cov = coverageByEntityType[kind];
    cov.total = entries.length;
    cov.totalWeight = entries.reduce((sum, e) => sum + (e.weight ?? 1), 0);

    let anyCovered = 0, anyWeight = 0;
    let docCovered = 0, docWeight = 0;
    let canonicalCovered = 0, canonicalWeight = 0;

    for (const entry of entries) {
      const slug = normalize(entry.id);
      const key = `${kind}\u0000${slug}`;
      const stab = maxStabilityByKey.get(key);
      const w = entry.weight ?? 1;

      if (stab !== undefined) {
        anyCovered += 1;
        anyWeight += w;
        if (stab === 'draft' || stab === 'canonical') {
          docCovered += 1;
          docWeight += w;
        }
        if (stab === 'canonical') {
          canonicalCovered += 1;
          canonicalWeight += w;
        }
      }
    }

    cov.tiers.any = {
      covered: anyCovered,
      rawCoverage: cov.total > 0 ? anyCovered / cov.total : 0,
      weightedCoverage: cov.totalWeight > 0 ? anyWeight / cov.totalWeight : 0,
    };
    cov.tiers.draftOrCanonical = {
      covered: docCovered,
      rawCoverage: cov.total > 0 ? docCovered / cov.total : 0,
      weightedCoverage: cov.totalWeight > 0 ? docWeight / cov.totalWeight : 0,
    };
    cov.tiers.canonical = {
      covered: canonicalCovered,
      rawCoverage: cov.total > 0 ? canonicalCovered / cov.total : 0,
      weightedCoverage: cov.totalWeight > 0 ? canonicalWeight / cov.totalWeight : 0,
    };
    // Legacy flat fields
    cov.covered = anyCovered;
    cov.percent = cov.tiers.any.rawCoverage * 100;
  }

  return {
    totalRecords: records.size,
    byStability,
    coverageByEntityType,
    untrackedKinds,
    weighting: {
      formula: 'sum of weights of covered entities / sum of all weights',
      notes: args.weightingNotes,
    },
  };
}

async function loadDefaultEntityUniverse(): Promise<Partial<Record<ProseEntityType, EntityUniverseInput>>> {
  // Load each registry lazily and emit string-array universes.
  const universe: Partial<Record<ProseEntityType, EntityUniverseInput>> = {};

  // Models + parameters (existing behavior).
  const [{ NATURAL_MODEL_REGISTRY }, { PARAMETER_REGISTRY }] = await Promise.all([
    import('../../src/natural/registry/registry'),
    import('../../src/natural/registry/parameterRegistry'),
  ]);
  universe.model = NATURAL_MODEL_REGISTRY.map((m: { id: string }) => m.id);
  universe.parameter = PARAMETER_REGISTRY.map((p: { id: string }) => p.id);

  // Primitives (added in prim-migration).
  try {
    const { PRIMITIVE_REGISTRY } = await import('../../src/natural/registry/primitiveRegistry');
    universe.primitive = PRIMITIVE_REGISTRY.map((p: { id: string }) => p.id);
  } catch {
    // registry not present — leave kind untracked
  }

  // Other kinds: leave untracked for now; the untrackedKinds field in the
  // report surfaces the gap. Adding them is a future sub-plan.
  return universe;
}

function formatText(r: ProseCoverageReport): string {
  const lines: string[] = [];
  lines.push(`Prose registry: ${r.totalRecords} record(s)`);
  lines.push(`  stability: stub=${r.byStability.stub}, draft=${r.byStability.draft}, canonical=${r.byStability.canonical}`);
  lines.push('Coverage by entity type (any / draft-or-canonical / canonical, raw / weighted):');
  for (const kind of Object.keys(r.coverageByEntityType).sort() as ProseEntityType[]) {
    const c = r.coverageByEntityType[kind];
    if (c.total > 0) {
      const t = c.tiers;
      lines.push(
        `  ${kind}: ${c.total} entities | any ${t.any.covered}/${c.total} (${(t.any.rawCoverage * 100).toFixed(1)}% raw, ${(t.any.weightedCoverage * 100).toFixed(1)}% wt) | doc ${t.draftOrCanonical.covered} (${(t.draftOrCanonical.rawCoverage * 100).toFixed(1)}%) | canon ${t.canonical.covered} (${(t.canonical.rawCoverage * 100).toFixed(1)}%)`,
      );
    }
  }
  if (Object.keys(r.untrackedKinds).length > 0) {
    lines.push('Untracked kinds (records exist but no universe provided):');
    for (const [k, n] of Object.entries(r.untrackedKinds).sort()) {
      lines.push(`  ${k}: ${n} record(s)`);
    }
  }
  return lines.join('\n');
}

async function main(): Promise<void> {
  const argv = process.argv.slice(2);
  const format = argv.includes('--format') ? argv[argv.indexOf('--format') + 1] : 'text';
  const strict = argv.includes('--strict');

  try {
    const universe = await loadDefaultEntityUniverse();
    const report = await computeProseCoverage({ entityUniverse: universe });
    if (format === 'json') {
      process.stdout.write(JSON.stringify(report, null, 2) + '\n');
    } else {
      process.stdout.write(formatText(report) + '\n');
    }

    if (strict && Object.keys(report.untrackedKinds).length > 0) {
      process.exit(2);
    }
  } catch (err) {
    process.stderr.write(
      `coverage-prose: ${err instanceof Error ? err.message : String(err)}\n`,
    );
    process.exit(1);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  await main();
}
```

