```ts
/**
 * @module src/natural/spec/correspondence/analytics/skeletonNormalization
 * @purpose The normalization / rewriting pre-pass for anti-unification (W3 of
 *   plan:0093-correspondence-realignment-program). AU is syntactic, so
 *   `∇²` vs `∂²ₓ` (equal in 1D) and cases-blocks must be canonicalized before
 *   LGG. This is a small, explicit rewrite layer — it complements the move
 *   layer, it does not encode semantic bridges (Cole–Hopf, Miura stay moves).
 * @related question:0122-is-derivation-stratum-generator-governing-law-derived-relation-solution
 * @related plan:0092-anti-unification-generator-nodes
 */

/** \frac{\partial^2 X}{\partial Y^2} or \partial^2 X / \partial Y^{2}  ->  \nabla^2 X (1D Laplacian). */
const SECOND_DERIV_FRAC =
  /\\frac\{\\partial\^2\s*(«\d+»)\}\{\\partial\s*«\d+»\^\{?2\}?\}/g;

export function normalizeSkeleton(latex: string): string {
  let out = latex;
  out = out.replace(SECOND_DERIV_FRAC, '\\nabla^2 $1');
  return out.trim();
}
```

**Run, see it pass.** Expected: 3 passed. Iterate the regex against real rows only as needed (the `«0»` in the numerator is captured; the spatial variable in the denominator is discarded — Laplacian abstracts over the coordinate, which is the point).

**Commit:** `feat(au): normalization pre-pass — 1D second derivative to Laplacian (W3)`

