```ts
import { extractFragmentFeatures } from '@/natural/spec/correspondence/analytics/derivationStrata';
function hasTime(latex: string): boolean {
  return extractFragmentFeatures(latex).features.time; // { features, firstToken } — read .features.time
}
export function selectPrincipal(fragments: string[]): string {
  const scored = fragments
    .map((latex) => ({ latex, time: hasTime(latex), m: mass(parseNormalized(latex)) }))
    .sort((a, b) => Number(b.time) - Number(a.time) || b.m - a.m);
  return scored[0]!.latex;
}
```

> This reuses `extractFragmentFeatures` (a pure, exported function — `derivationStrata.ts:91`) rather than re-exporting the private `TIME_PATTERNS`, so there is no extra `derivationStrata.ts` edit and no parallel-constant drift (`D-004`).

