```ts
export interface ClusterLgg { lgg: Term; rendered: string; steps: string[]; mass: number; }
export function clusterLgg(fragments: string[]): ClusterLgg {
  const terms = fragments.map(parseNormalized);
  let acc = terms[0]!;
  const steps = [render(acc)];
  for (let i = 1; i < terms.length; i++) {
    acc = lgg(acc, terms[i]!, new Map());
    steps.push(render(acc));
  }
  return { lgg: acc, rendered: render(acc), steps, mass: mass(acc) };
}
```

