```ts
export interface GeneratorCandidate {
  id: string;            // `candidate:<seed-model>` — NEVER a `skel:` id (proposals only)
  members: string[];
  skeleton: string;      // rendered LGG (holes as ?)
  mass: number;
  meanSimilarity: number;
  matchesExistingSkel?: string; // optional: a skel: id this LGG matches, for the human curator
}
export interface ProposeOptions { minSimilarity: number; minMembers: number; }

export function proposeGenerators(
  principals: Record<string, string>,
  opts: ProposeOptions,
): GeneratorCandidate[] { /* single-linkage clustering + clusterLgg per cluster */ }
```

