**Minimal implementation** `scripts/audit/anti-unification-generators.ts`:

```ts
#!/usr/bin/env tsx
/**
 * W3 driver (plan:0092-anti-unification-generator-nodes): reads the bare
 * skeleton substrate, runs cluster-LGG over the full catalog, and writes a
 * candidate-generator REPORT. It MUST NOT write any canonical registry — the
 * report feeds W5 / task:t254 where a human authors FormulaPoints by hand.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  normalizeSkeleton, selectPrincipal, proposeGenerators,
} from '../../src/natural/spec/correspondence/analytics/antiUnification';

interface Row { model_id: string; fragment_kind: string; tight_skeleton: string; }

export function buildPrincipalsByModel(rows: Row[]): Record<string, string> {
  const byModel = new Map<string, string[]>();
  for (const r of rows) {
    if (r.fragment_kind !== 'equation') continue;
    (byModel.get(r.model_id) ?? byModel.set(r.model_id, []).get(r.model_id)!)
      .push(normalizeSkeleton(r.tight_skeleton));
  }
  const out: Record<string, string> = {};
  for (const [model, frags] of byModel) out[model] = selectPrincipal(frags);
  return out;
}

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const FRAGMENTS = resolve(REPO, 'src/chapters/generated/formula-skeletons-bare.json');
const OUT = resolve(REPO, 'pipeline/q121/generator-candidates.json');

function main(): void {
  const rows = JSON.parse(readFileSync(FRAGMENTS, 'utf8')) as Row[];
  const principals = buildPrincipalsByModel(rows);
  const candidates = proposeGenerators(principals, { minSimilarity: 0.5, minMembers: 2 });
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, `${JSON.stringify({ generatedAt: '2026-05-29', candidates }, null, 2)}\n`);
  console.log(`-> ${OUT}  (${candidates.length} candidate generators)`);
}

// run only when invoked directly, so the test can import buildPrincipalsByModel
if (import.meta.url === `file://${process.argv[1]}`) main();
```

