**Minimal implementation** `src/natural/spec/correspondence/analytics/compositionLaw.ts` — port the max-min loop from `t590EndpointComputation.ts:140-193` verbatim, but take `units: readonly { unitId: string }[]` (or `string[]`) and an injected `simOf(aId, bId) => number`:

```ts
/**
 * @module src/natural/spec/correspondence/analytics/compositionLaw
 * @purpose Endpoint-agnostic hypothesis:0002-enriched-categorical-lenses max-min composition law. A pair (i,k) violates when its DIRECT
 *   similarity is below the best MEDIATED similarity max_m min(sim(i,m), sim(m,k)). Extracted from the
 *   frozen FieldCount path (t590EndpointComputation) so the FieldCount and the AU-structural endpoints
 *   share one tested implementation. PURE: similarity is injected; no data dependency.
 * @related question:0122-is-derivation-stratum-generator-governing-law-derived-relation-solution
 * @related task:t590
 */
export interface CompositionViolation {
  sourceUnitId: string;
  targetUnitId: string;
  directSimilarity: number;
  bestMediatingUnitId: string;
  bestMediatedSimilarity: number;
}
export interface CompositionViolationResult {
  unitCount: number;
  totalPairs: number;
  violationCount: number;
  violationRate: number;
  violations: CompositionViolation[];
}
export function computeCompositionViolations(
  unitIds: readonly string[],
  simOf: (a: string, b: string) => number,
): CompositionViolationResult {
  if (unitIds.length < 2) {
    return { unitCount: unitIds.length, totalPairs: 0, violationCount: 0, violationRate: 0, violations: [] };
  }
  const violations: CompositionViolation[] = [];
  let totalPairs = 0;
  for (let i = 0; i < unitIds.length; i += 1) {
    for (let k = i + 1; k < unitIds.length; k += 1) {
      totalPairs += 1;
      const directSimilarity = simOf(unitIds[i], unitIds[k]);
      let bestMediatedSimilarity = Number.NEGATIVE_INFINITY;
      let bestMediatingUnitId = unitIds[i];
      for (const m of unitIds) {
        const mediated = Math.min(simOf(unitIds[i], m), simOf(m, unitIds[k]));
        if (mediated > bestMediatedSimilarity) { bestMediatedSimilarity = mediated; bestMediatingUnitId = m; }
      }
      if (directSimilarity < bestMediatedSimilarity) {
        violations.push({ sourceUnitId: unitIds[i], targetUnitId: unitIds[k], directSimilarity, bestMediatingUnitId, bestMediatedSimilarity });
      }
    }
  }
  return { unitCount: unitIds.length, totalPairs, violationCount: violations.length, violationRate: totalPairs === 0 ? 0 : violations.length / totalPairs, violations };
}
```

