**Minimal implementation** `src/natural/spec/correspondence/analytics/auStructuralEndpoint.ts`:

```ts
/**
 * @module src/natural/spec/correspondence/analytics/auStructuralEndpoint
 * @purpose The question:0121-edgecategory-verification-instrument stratum-aware successor endpoint. Replaces FieldCount with AU structural
 *   similarity (Dice on LGG mass over alpha-normalized principal skeletons) and runs the shared
 *   max-min composition law over each cluster's FamilyHandle units. PURE: skeletons are injected
 *   (from the committed q121-au-skeleton-profiles artifact by the driver). The frozen FieldCount
 *   endpoint (t590EndpointComputation) is untouched.
 * @related question:0122-is-derivation-stratum-generator-governing-law-derived-relation-solution
 * @related report:0064-q121-fieldcount-by-stratum-postmortem
 * @related task:t618
 */
import { parseNormalized, similarity } from './antiUnification';
import { computeCompositionViolations, type CompositionViolationResult } from './compositionLaw';

/** AU structural similarity (Dice on LGG mass) over two normalized skeletons. */
export function auSkeletonSimilarity(a: string, b: string): number {
  return similarity(parseNormalized(a), parseNormalized(b)).sim;
}

export interface AuFamilyUnit { unitId: string; slug: string; }
export interface AuFamilyViolationResult {
  resolvedUnitIds: string[];
  unresolvedUnitIds: string[];
  violation: CompositionViolationResult;
}

/** Run the composition law over the family units whose slug resolves to a non-null skeleton.
 *  `skeletonOf(slug)` returns the committed normalized principal skeleton, or null/undefined. */
export function computeAuFamilyViolations(
  units: readonly AuFamilyUnit[],
  skeletonOf: (slug: string) => string | null | undefined,
): AuFamilyViolationResult {
  const skelById = new Map<string, string>();
  const resolved: string[] = [];
  const unresolved: string[] = [];
  for (const u of units) {
    const s = skeletonOf(u.slug);
    if (s) { skelById.set(u.unitId, s); resolved.push(u.unitId); } else unresolved.push(u.unitId);
  }
  const violation = computeCompositionViolations(resolved, (x, y) =>
    auSkeletonSimilarity(skelById.get(x) as string, skelById.get(y) as string),
  );
  return { resolvedUnitIds: resolved, unresolvedUnitIds: unresolved, violation };
}
```

